-- =====================================================================
-- AZ/seed_past_elections.sql
--
-- FIVE finished past elections (2019-2020 .. 2023-2024), each with its own
-- parties, candidates, votes and proclaimed winners, plus the 061 archive
-- snapshot.  This is the data the homepage "Past Election" tab renders.
--
-- WHY THESE PERIODS SHOW UP
--   list_past_elections_rpc filters on (061:569-573)
--     e.is_active = false and (e.results_published = true
--                              or a past_election_periods snapshot exists)
--   Every period below is therefore is_active = false, results_published =
--   true, proclaimed = true and lifecycle_stage = 'completed', AND it is
--   snapshotted at the end of this file.  lifecycle_stage = 'completed' also
--   keeps them out of current_election_period_id(), so the live election is
--   untouched.
--
-- SHAPE PER PERIOD
--   4 parties x 13 positions  = 52 approved candidates   (260 total)
--   40 voters x 13 positions  = 520 vote rows            (2600 total)
--     of which 2 per position are abstentions (candidate_id null, abstained
--     true), so abstention tallies are non-zero too.
--   Vote counts per position are 40/30/20/10-ish and always DISTINCT, so
--   there is exactly ONE is_winner per position and the proclamations
--   unique (election_period_id, winning_position) is never violated.
--
-- IDS ARE DETERMINISTIC
--   Periods  5a000000-...-00000000000N
--   Parties  5b000000-...-00000000000N
--   Candidates 5c000000-...-00000000000N
--   Fixed ids are what make the file re-runnable and the votes/proclamations
--   referenceable by literal.
--
-- PREREQUISITE
--   AZ/seed_students_300.sql must have been run: candidates and voters are
--   resolved from public.students by lrn (999900000001 .. 999900000280).
--   The guard below aborts if those rows are missing -- the join would
--   otherwise silently drop every row.
--
-- RE-RUNNABLE
--   The file first deletes anything it previously created (scoped to the
--   five fixed period ids) and rebuilds it.  election_periods has a
--   retention trigger that rejects DELETE, so it is disabled for the
--   duration and re-enabled at the end; the whole file is one transaction,
--   so a failure rolls the disable back too.
--
--   This does NOT touch the current election period, parties, candidates or
--   votes.
-- =====================================================================

begin;

-- ---------------------------------------------------------------------
-- 0. Preconditions
-- ---------------------------------------------------------------------
do $$
declare
  v_count integer;
begin
  select count(*) into v_count
  from public.students
  where lrn like '9999%';

  if v_count < 300 then
    raise exception
      'Found % synthetic students (lrn 9999%%), expected 300. Run AZ/seed_students_300.sql first.',
      v_count;
  end if;

  if to_regclass('public.past_election_periods') is null then
    raise exception
      'public.past_election_periods is missing. Apply supabase/migrations/061_past_election_candidates.sql first.';
  end if;
end $$;

-- ---------------------------------------------------------------------
-- 1. Clear any previous run of THIS seed (its five period ids only)
-- ---------------------------------------------------------------------
do $$
begin
  if exists (
    select 1 from pg_trigger
    where tgrelid = 'public.election_periods'::regclass
      and tgname = 'election_periods_no_delete'
      and not tgisinternal
  ) then
    execute 'alter table public.election_periods disable trigger election_periods_no_delete';
  end if;
end $$;

do $$
begin
  if to_regclass('public.proclamations') is not null then
    delete from public.proclamations where election_period_id = any (array['5a000000-0000-4000-8000-000000000001'::uuid, '5a000000-0000-4000-8000-000000000002'::uuid, '5a000000-0000-4000-8000-000000000003'::uuid, '5a000000-0000-4000-8000-000000000004'::uuid, '5a000000-0000-4000-8000-000000000005'::uuid]);
  end if;
end $$;

delete from public.votes                     where election_period_id = any (array['5a000000-0000-4000-8000-000000000001'::uuid, '5a000000-0000-4000-8000-000000000002'::uuid, '5a000000-0000-4000-8000-000000000003'::uuid, '5a000000-0000-4000-8000-000000000004'::uuid, '5a000000-0000-4000-8000-000000000005'::uuid]);
delete from public.candidates                where election_period_id = any (array['5a000000-0000-4000-8000-000000000001'::uuid, '5a000000-0000-4000-8000-000000000002'::uuid, '5a000000-0000-4000-8000-000000000003'::uuid, '5a000000-0000-4000-8000-000000000004'::uuid, '5a000000-0000-4000-8000-000000000005'::uuid]);
delete from public.parties                   where election_period_id = any (array['5a000000-0000-4000-8000-000000000001'::uuid, '5a000000-0000-4000-8000-000000000002'::uuid, '5a000000-0000-4000-8000-000000000003'::uuid, '5a000000-0000-4000-8000-000000000004'::uuid, '5a000000-0000-4000-8000-000000000005'::uuid]);
delete from public.past_election_candidates  where election_period_id = any (array['5a000000-0000-4000-8000-000000000001'::uuid, '5a000000-0000-4000-8000-000000000002'::uuid, '5a000000-0000-4000-8000-000000000003'::uuid, '5a000000-0000-4000-8000-000000000004'::uuid, '5a000000-0000-4000-8000-000000000005'::uuid]);
delete from public.past_election_positions   where election_period_id = any (array['5a000000-0000-4000-8000-000000000001'::uuid, '5a000000-0000-4000-8000-000000000002'::uuid, '5a000000-0000-4000-8000-000000000003'::uuid, '5a000000-0000-4000-8000-000000000004'::uuid, '5a000000-0000-4000-8000-000000000005'::uuid]);
delete from public.past_election_periods     where election_period_id = any (array['5a000000-0000-4000-8000-000000000001'::uuid, '5a000000-0000-4000-8000-000000000002'::uuid, '5a000000-0000-4000-8000-000000000003'::uuid, '5a000000-0000-4000-8000-000000000004'::uuid, '5a000000-0000-4000-8000-000000000005'::uuid]);
delete from public.election_periods          where id = any (array['5a000000-0000-4000-8000-000000000001'::uuid, '5a000000-0000-4000-8000-000000000002'::uuid, '5a000000-0000-4000-8000-000000000003'::uuid, '5a000000-0000-4000-8000-000000000004'::uuid, '5a000000-0000-4000-8000-000000000005'::uuid]);

do $$
begin
  if exists (
    select 1 from pg_trigger
    where tgrelid = 'public.election_periods'::regclass
      and tgname = 'election_periods_no_delete'
      and not tgisinternal
  ) then
    execute 'alter table public.election_periods enable trigger election_periods_no_delete';
  end if;
end $$;

-- ---------------------------------------------------------------------
-- 2. The five election periods (finished + published + proclaimed)
-- ---------------------------------------------------------------------
insert into public.election_periods
  (id, school_year, venue, voting_method, candidacy_open, is_active,
   results_published, proclaimed, proclaimed_at, election_date, end_date,
   start_time, end_time, lifecycle_stage)
values
