  ('5a000000-0000-4000-8000-000000000002', '2020-2021', 'CNNHS Covered Court', 'plurality', false, false, true, true, '2020-10-11 16:00:00+08:00'::timestamptz, '2020-10-09', '2020-10-09', '08:00', '18:00', 'completed'),
  ('5a000000-0000-4000-8000-000000000003', '2021-2022', 'CNNHS Gymnasium', 'plurality', false, false, true, true, '2021-10-10 16:00:00+08:00'::timestamptz, '2021-10-08', '2021-10-08', '08:00', '18:00', 'completed'),
  ('5a000000-0000-4000-8000-000000000004', '2022-2023', 'CNNHS Covered Court', 'plurality', false, false, true, true, '2022-10-09 16:00:00+08:00'::timestamptz, '2022-10-07', '2022-10-07', '08:00', '18:00', 'completed'),
  ('5a000000-0000-4000-8000-000000000005', '2023-2024', 'CNNHS Gymnasium', 'plurality', false, false, true, true, '2023-10-08 16:00:00+08:00'::timestamptz, '2023-10-06', '2023-10-06', '08:00', '18:00', 'completed');

