join public.students s on s.lrn = v.lrn;

-- ---------------------------------------------------------------------
-- 6. Proclamations -- top vote-getter per position, straight from the
--    votes just written, so past_election_candidates.proclaimed_winner
--    resolves.  Guarded: the table is optional in some deployments.
-- ---------------------------------------------------------------------
do $$
begin
  if to_regclass('public.proclamations') is not null then
    insert into public.proclamations
      (election_period_id, winning_position, candidate_id, votes)
    select w.election_period_id, w.position, w.candidate_id, w.votes
    from (
      select
        v.election_period_id,
        v."position" as position,
        v.candidate_id,
        count(*)::integer as votes,
        row_number() over (
          partition by v.election_period_id, v."position"
          order by count(*) desc, v.candidate_id
        ) as rn
      from public.votes v
      where v.election_period_id = any (array['5a000000-0000-4000-8000-000000000001'::uuid, '5a000000-0000-4000-8000-000000000002'::uuid, '5a000000-0000-4000-8000-000000000003'::uuid, '5a000000-0000-4000-8000-000000000004'::uuid, '5a000000-0000-4000-8000-000000000005'::uuid])
        and v.candidate_id is not null
      group by v.election_period_id, v."position", v.candidate_id
    ) w
    where w.rn = 1;
  end if;
end $$;

-- ---------------------------------------------------------------------
-- 7. Freeze each period into the 061 snapshot tables.  Called as the
--    owner: archive_past_election_results_rpc is gated on an Electoral
--    Board / chief commissioner session, which the SQL editor has none of.
-- ---------------------------------------------------------------------

select public.archive_election_results_internal('5a000000-0000-4000-8000-000000000001');
select public.archive_election_results_internal('5a000000-0000-4000-8000-000000000002');
select public.archive_election_results_internal('5a000000-0000-4000-8000-000000000003');
select public.archive_election_results_internal('5a000000-0000-4000-8000-000000000004');
select public.archive_election_results_internal('5a000000-0000-4000-8000-000000000005');

commit;

-- ---------------------------------------------------------------------
-- Verify: expecting 5 periods, 20 parties, 260 candidates, 2600 votes,
-- 65 snapshot position rows, 260 snapshot candidate rows.
-- ---------------------------------------------------------------------
select
  (select count(*) from public.election_periods
     where id = any (array['5a000000-0000-4000-8000-000000000001'::uuid, '5a000000-0000-4000-8000-000000000002'::uuid, '5a000000-0000-4000-8000-000000000003'::uuid, '5a000000-0000-4000-8000-000000000004'::uuid, '5a000000-0000-4000-8000-000000000005'::uuid]))                        as periods,
  (select count(*) from public.parties
     where election_period_id = any (array['5a000000-0000-4000-8000-000000000001'::uuid, '5a000000-0000-4000-8000-000000000002'::uuid, '5a000000-0000-4000-8000-000000000003'::uuid, '5a000000-0000-4000-8000-000000000004'::uuid, '5a000000-0000-4000-8000-000000000005'::uuid]))        as parties,
  (select count(*) from public.candidates
     where election_period_id = any (array['5a000000-0000-4000-8000-000000000001'::uuid, '5a000000-0000-4000-8000-000000000002'::uuid, '5a000000-0000-4000-8000-000000000003'::uuid, '5a000000-0000-4000-8000-000000000004'::uuid, '5a000000-0000-4000-8000-000000000005'::uuid]))        as candidates,
  (select count(*) from public.votes
     where election_period_id = any (array['5a000000-0000-4000-8000-000000000001'::uuid, '5a000000-0000-4000-8000-000000000002'::uuid, '5a000000-0000-4000-8000-000000000003'::uuid, '5a000000-0000-4000-8000-000000000004'::uuid, '5a000000-0000-4000-8000-000000000005'::uuid]))        as votes,
  (select count(*) from public.votes
     where election_period_id = any (array['5a000000-0000-4000-8000-000000000001'::uuid, '5a000000-0000-4000-8000-000000000002'::uuid, '5a000000-0000-4000-8000-000000000003'::uuid, '5a000000-0000-4000-8000-000000000004'::uuid, '5a000000-0000-4000-8000-000000000005'::uuid])
       and abstained)                                          as abstentions,
  (select count(*) from public.past_election_positions
     where election_period_id = any (array['5a000000-0000-4000-8000-000000000001'::uuid, '5a000000-0000-4000-8000-000000000002'::uuid, '5a000000-0000-4000-8000-000000000003'::uuid, '5a000000-0000-4000-8000-000000000004'::uuid, '5a000000-0000-4000-8000-000000000005'::uuid]))        as snap_positions,
  (select count(*) from public.past_election_candidates
     where election_period_id = any (array['5a000000-0000-4000-8000-000000000001'::uuid, '5a000000-0000-4000-8000-000000000002'::uuid, '5a000000-0000-4000-8000-000000000003'::uuid, '5a000000-0000-4000-8000-000000000004'::uuid, '5a000000-0000-4000-8000-000000000005'::uuid]))        as snap_candidates,
  (select count(*) from public.past_election_candidates
     where election_period_id = any (array['5a000000-0000-4000-8000-000000000001'::uuid, '5a000000-0000-4000-8000-000000000002'::uuid, '5a000000-0000-4000-8000-000000000003'::uuid, '5a000000-0000-4000-8000-000000000004'::uuid, '5a000000-0000-4000-8000-000000000005'::uuid])
       and is_winner)                                          as snap_winners;

-- One row per period, as the Past Election tab will read it.
select
  e.school_year,
  e.election_date,
  e.venue,
  e.proclaimed,
  pep.positions_contested,
  pep.approved_candidates,
  pep.votes_cast,
  pep.abstentions,
  pep.total_ballots
from public.election_periods e
join public.past_election_periods pep on pep.election_period_id = e.id
where e.id = any (array['5a000000-0000-4000-8000-000000000001'::uuid, '5a000000-0000-4000-8000-000000000002'::uuid, '5a000000-0000-4000-8000-000000000003'::uuid, '5a000000-0000-4000-8000-000000000004'::uuid, '5a000000-0000-4000-8000-000000000005'::uuid])
order by e.election_date;
